function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = [];
  let reorderedSentence = '';

  // 1. Identify Adjectives:
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to reliably detect adjectives (see below)
      adjectiveIndices.push(i);
    }
  }

  // 2. Reorder and Reconstruct:
  if (adjectiveIndices.length >= 2) {  // Ensure at least two adjectives for swapping
    const [firstAdjIndex, secondAdjIndex] = adjectiveIndices.slice(0, 2);
    const temp = words[firstAdjIndex];
    words[firstAdjIndex] = words[secondAdjIndex];
    words[secondAdjIndex] = temp;
  }

  reorderedSentence = words.join(' ');
  return reorderedSentence;
}

// Helper function (expandable for more robust adjective detection)
function isAdjective(word) {
  // Simple rule-of-thumb based approach (can be refined with NLP techniques)
  return !/[^a-zA-Z]+/.test(word) && !/[0-9]+/.test(word) &&  // Mostly letters, no numbers
         /(adjective-like pattern)/.test(word); // Placeholder for  advanced pattern matching
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park
```

