// Recursive Fibonacci function with error handling
pair<long long, bool> fibonacciRecursive(long long a, long long b, int n, bool& isValid) {
    if (n <= 0) {  // Base case: Generate zero elements, return valid flag
        isValid = true;
        return make_pair(0, true);
    } else if (n == 1) {  // Base case: Return the first element
        isValid = true;
        return make_pair(a, true);
