namespace GenericRestServiceWrapper
{
    public class RestServiceWrapper<T> where T : class
    {
        private readonly string _baseUrl;
        private readonly HttpClient _httpClient;
        private readonly Func<string, string> _authTokenProvider;

        public RestServiceWrapper(string baseUrl, Func<string, string> authTokenProvider)
        {
            _baseUrl = baseUrl;
            _httpClient = new HttpClient { BaseAddress = new Uri(baseUrl) };
            _authTokenProvider = authTokenProvider; 
        }

        /// <summary>
        /// Makes a GET request to the specified endpoint with auth token handling.
        /// </summary>
        /// <param name="endpoint">Relative endpoint path (e.g., "/users/{userId}")</param>
        /// <param name="parameters">Dictionary of query parameters (optional)</param>
        /// <returns>Task containing the deserialized T object on success, or an exception on error.</returns>
        public async Task<T> GetAsync(string endpoint, params KeyValuePair<string, string>[] parameters)
        {
            var uriBuilder = new UriBuilder(_httpClient.BaseAddress) { Path = endpoint };
            if (parameters != null && parameters.Length > 0)
            {
                uriBuilder.Query = System.Web.HttpUtility.ParseQueryString(string.Empty);
                foreach (var param in parameters)
                    uriBuilder.Query[param.Key] = param.Value;
            }

            string authToken = _authTokenProvider(endpoint); // Fetch token dynamically if needed per endpoint
            AddAuthenticationHeader(authToken);

            HttpResponseMessage response = await _httpClient.GetAsync(uriBuilder.Uri);
            HandleResponse(response); 

            return await DeserializeObject<T>(response);
        }

        /// <summary>
        ///  POST request with data serialization and auth handling.
        /// </summary>
        /// <param name="endpoint">Relative endpoint path</param>
        /// <param name="data">Object to serialize and send in the request body</param>
