function geocodePlaceNames(spreadsheet, sheetName, placeColumn, latColumn, lngColumn) {
  // 1. Access Spreadsheet & Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names & Iterate
  const dataRange = sheet.getRange(placeColumn); // Assuming your place names are in a single column
  const placeValues = dataRange.getValues().flat(); // Extract place names into an array

  for (let i = 0; i < placeValues.length; i++) {
    const placeName = placeValues[i];
    // 3. Geocoding using Places API (Requires API Key setup)
    const geocoder = new google.maps.Geocoder();
    const request = { address: placeName };
    geocoder.geocode(request, function(results, status) {
      if (status === google.maps.GeocoderStatus.OK && results.length > 0) {
        const latitude = results[0].geometry.location.lat();
        const longitude = results[0].geometry.location.lng();

        // 4. Update Spreadsheet with Lat/Long
        const row = i + 1; // Adjust for zero-based indexing
        sheet.getRange(row, latColumn).setValue(latitude);
        sheet.getRange(row, lngColumn).setValue(longitude);
        Logger.log(`Geocoded ${placeName} - Lat: ${latitude}, Lng: ${longitude}`);
      } else {
        Logger.log(`Error geocoding ${placeName}: ${status}`);
        // Handle geocoding failures (e.g., missing data, API limits)
      }
    });
  }
}
```

