<?php

function smart_sort_array(array $set, string $order = 'asc'): array {
    usort($set, function ($a, $b) use ($order) {
        // Compare ages using ternary operator for concise order handling
        return $order === 'asc' ? ($a['age'] - $b['age']) : ($b['age'] - $a['age']);
    });
    return $set;
}

// Example Usage:
$data = [
    ['name' => 'Alice', 'address' => 'City A', 'age' => 25],
    ['name' => 'Bob', 'address' => 'City B', 'age' => 30],
    ['name' => 'Charlie', 'address' => 'City C', 'age' => 20]
];

// Sort in ascending order (default)
$sortedAsc = smart_sort_array($data);
print_r($sortedAsc); // Output: Array sorted by age in ascending order

// Sort in descending order
$sortedDesc = smart_sort_array($data, 'desc');
print_r($sortedDesc); // Output: Array sorted by age in descending order

?>
